import { useAtom, useAtomValue } from "jotai";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { MatrixService } from "modules/matrix-client/services/matrix-service";
import { PushNotificationsAtoms } from "modules/push-notifications/jotai";
import { PushNotificationsService } from "modules/push-notifications/service";
import { type FC, useEffect } from "react";

export const PushNotificationServiceController: FC = () => {
  const permissions = useAtomValue(PushNotificationsAtoms.isPermitted);
  const client = useAtomValue(MatrixAtoms.matrixClient);
  const [token, setToken] = useAtom(PushNotificationsAtoms.token);

  // Register notification listeners when permissions are granted
  useEffect(() => {
    if (!permissions) return;
    PushNotificationsService.registerListeners().catch((e) => {
      console.warn("Failed to register notification listeners:", e);
    });
  }, [permissions]);

  // Get FCM token when permissions are granted
  useEffect(() => {
    if (!permissions || !!token) return;

    const getFCMToken = async () => {
      try {
        const fcmToken = await PushNotificationsService.getToken();
        setToken(fcmToken);
      } catch (e) {
        console.warn("Failed to get FCM token:", e);
      }
    };
    getFCMToken();
  }, [permissions, token, setToken]);

  // Handle pusher registration/unregistration based on permissions
  useEffect(() => {
    if (!token || !permissions || !client) return;

    const handlePusherState = async () => {
      try {
        // Check if pusher is already registered on the server
        const isRegistered = await MatrixService.isPusherRegistered(token);

        if (permissions && isRegistered) return;

        if (permissions && !isRegistered) {
          await PushNotificationsService.registerPusher();
          return;
        }

        if (!permissions && isRegistered) {
          await PushNotificationsService.unregisterPusher();
        }
      } catch (e) {
        console.warn("Failed to handle pusher state:", e);
      }
    };

    handlePusherState();
  }, [token, permissions, client]);

  return <></>;
};

