import notifee, {
  AndroidImportance,
  AndroidVisibility,
  EventType,
  type Notification,
} from "@notifee/react-native";
import { CommonActions } from "@react-navigation/native";
import { NavigationContainerRef } from "modules/navigation/const";

type CreatePayload = {
  message: string;
  title?: string;
  data?: Notification["data"];
  id: string;
};

export class NotifeeService {
  private static channelId = "local-push-notifications";

  public static init = async () => {
    await notifee.createChannel({
      id: "local-push-notifications",
      name: "Local push notifications",
      sound: "default",
      importance: AndroidImportance.HIGH,
      visibility: AndroidVisibility.PUBLIC,
    });

    // Handle notification press when app is in foreground
    notifee.onForegroundEvent((event) => {
      if (event.type === EventType.PRESS) {
        this.handleNotificationPress(event.detail.notification);
      }
    });

    notifee.onBackgroundEvent(async (event) => {
      if (event.type === EventType.PRESS) {
        this.handleNotificationPress(event.detail.notification);
      }
    });

    // Check if app was opened from a notification
    const initialNotification = await notifee.getInitialNotification();
    if (initialNotification?.notification) {
      this.handleNotificationPress(initialNotification.notification);
    }
  };

  private static handleNotificationPress = (
    notification: Notification | undefined,
  ) => {
    const roomId = notification?.data?.room_id;
    if (roomId && typeof roomId === "string") {
      NavigationContainerRef.dispatch(
        CommonActions.navigate("room", {
          roomId,
        }),
      );
    }
  };

  public static create = (payload: CreatePayload) =>
    notifee.displayNotification({
      android: {
        pressAction: { id: "default" },
        channelId: this.channelId,
        autoCancel: true,
        color: "#292929",
      },
      title: payload.title,
      body: payload.message,
      id: payload.id,
      data: payload.data,
    });
}

export const MATRIX_ENDPOINTS = {
  PUSHERS_GET: "_matrix/client/v3/pushers",
  PUSHERS_SET: "_matrix/client/v3/pushers/set",
  PUSH_GATEWAY_URL: "_matrix/push/v1/notify",
  PUSH_RULES_GET: "_matrix/client/v3/pushrules/",
  PUSH_RULES_SET: "_matrix/client/v3/pushrules/",
  PUSH_RULES_ENABLE: "_matrix/client/v3/pushrules/",
};

