   146→        throw new Error("Failed to initialize sync service");
   147→      }
   148→
   149→      await this.syncService.start();
   150→
   151→      // Update atoms so providers can react to the initialized service
   152→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   153→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   154→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   155→
   156→      return true;
   157→    } catch (error) {
   158→      console.warn("Failed to restore session:", error);
   159→
   160→      // Clear both credentials and crypto store to ensure clean state
   161→      MatrixStorage.clearLoginCredentials();
   162→      await this.clearCryptoStore();
   163→
   164→      // Reset the instance so it can be recreated fresh
   165→      this.instance = null;
   166→      this.syncService = null;
   167→
   168→      // Clear atoms
   169→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   170→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   171→
   172→      return false;
   173→    }
   174→  };
