   396→  public static deactivateAccount = async (password: string) => {
   397→    if (!this.instance) throw new Error("Client not initialized");
   398→
   399→    try {
   400→      // First request with undefined auth_data (will always fail per UIA spec)
   401→      try {
   402→        await this.instance.deactivateAccount(undefined, true);
   403→      } catch {
   404→        // Expected to fail
   405→      }
   406→
   407→      console.log(this.instance.userId(), "userId");
   408→      const userId = this.instance.userId();
   409→      if (!userId) throw new Error("User ID not found");
   410→
   411→      const authData = new AuthData.Password({
   412→        passwordDetails: AuthDataPasswordDetails.create({
   413→          identifier: userId,
   414→          password,
   415→        }),
   416→      });
   417→
   418→      // Step 4: Second request with auth data
   419→      await this.instance.deactivateAccount(authData, true);
   420→
   421→      // After successful deactivation, clean up local data
   422→      await this.logout();
   423→    } catch (error) {
