   592→  public static getReadReceipts = async (event: EventTimelineItem) => {
   593→    const userIds = Array.from(event.readReceipts.keys()).map(
   594→      (userIds) => userIds,
   595→    );
   596→
   597→    // Don't show read receipts for the sender's own message
   598→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
   599→
   600→    if (!filteredUserIds.length) {
   601→      return [];
   602→    }
   603→
   604→    try {
   605→      const profilePromises = filteredUserIds.map((userId) =>
   606→        this.instance?.getProfile(userId),
   607→      );
   608→      const profiles = await Promise.allSettled(profilePromises);
   609→      return profiles
   610→        .filter((p) => p.status === "fulfilled")
   611→        .map((p) => p.value)
   612→        .filter((p) => p !== undefined);
   613→    } catch (error) {
   614→      console.error("Failed to get read receipt users:", error);
   615→      return [];
   616→    }
   617→  };
