import type { DocumentPickerResponse } from "@react-native-documents/picker";
import {
  AuthData,
  AuthDataPasswordDetails,
  ClientBuilder,
  type ClientInterface,
  type CreateRoomParameters,
  type EnableRecoveryProgressListener,
  type EventTimelineItem,
  Membership,
  messageEventContentFromMarkdown,
  PowerLevel_Tags,
  RecoveryState,
  RoomPreset,
  RoomVisibility,
  type Session,
  type SessionVerificationControllerDelegate,
  type SessionVerificationControllerInterface,
  type SessionVerificationData,
  SessionVerificationData_Tags,
  type SessionVerificationRequestDetails,
  SlidingSyncVersion,
  type SyncServiceInterface,
  UploadSource,
  type UserProfile,
  VerificationState,
} from "@unomed/react-native-matrix-sdk";
import { deleteJotaiStorageAdapter } from "modules/storage/utils";
import RNFS from "react-native-fs";
import { MATRIX_ENDPOINTS, MatrixStorage, SygnalURL } from "../const";
import { MatrixJotaiStore } from "../const/matrx-jotai-store";
import { MatrixAtoms } from "../jotai";

type LoginWithUsernameAndPasswordData = {
  username: string;
  password: string;
  serverUrl: string;
};

/** Callback function for verification request received */
type VerificationRequestCallback = (
  details: SessionVerificationRequestDetails,
) => void;

/** Callback function for emojis received during verification */
type VerificationEmojisCallback = (
  emojis: Array<{ symbol: string; description: string }>,
) => void;

/** Callback function for verification state changes */
type VerificationStateChangeCallback = (
  state: "request" | "emojis" | "success" | "failed" | "cancelled",
) => void;

const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;

const APP_ID = "com.prototyp.cloak";

export class MatrixService {
  //TODO: change every method that uses MatrixService.instance to a class method
  public static instance: ClientInterface | null;
  public static syncService: SyncServiceInterface | null;
  private static verificationController: SessionVerificationControllerInterface | null =
    null;
  public static profile: UserProfile | null = null;

  // Verification callbacks
  private static onVerificationRequest: VerificationRequestCallback | null =
    null;
  private static onVerificationEmojis: VerificationEmojisCallback | null = null;
  private static onVerificationStateChange: VerificationStateChangeCallback | null =
    null;

  /** Clear the crypto store directories to fix device ID mismatches */
  private static async clearCryptoStore() {
    try {
      const dataExists = await RNFS.exists(dataPath);
      const cacheExists = await RNFS.exists(cachePath);

      if (dataExists) {
        await RNFS.unlink(dataPath);
        console.log("Cleared crypto data store");
      }

      if (cacheExists) {
        await RNFS.unlink(cachePath);
        console.log("Cleared crypto cache store");
      }
    } catch (error) {
      console.warn("Failed to clear crypto store:", error);
    }
  }

  /** Initialize client with error handling for RTC warnings */
  public static async initialize(serverUrl: string) {
    if (!this.instance) {
      this.instance = await new ClientBuilder()
        .homeserverUrl(serverUrl)
        .autoEnableBackups(true)
        .sessionPaths(dataPath, cachePath) // enables persistent stores (needed for E2EE)
        .build();
    }
  }

  // public static isLoggedIn = () => this.instance.isLoggedIn();

  /** Check if there are stored credentials available for auto-login */
  public static hasStoredCredentials = (): boolean => {
    return MatrixStorage.hasStoredCredentials();
  };

  /** Attempt to restore session from stored credentials */
  public static restoreSession = async (): Promise<boolean> => {
    try {
      const credentials = MatrixStorage.getLoginCredentials();

      if (!credentials) return false;

      await this.initialize(credentials.baseUrl);

      if (!this.instance) throw new Error("Failed to initialize client");

      // Create client with stored credentials
      await this.instance.restoreSession({
        accessToken: credentials.accessToken,
        refreshToken: credentials.refreshToken,
        userId: credentials.userId,
        deviceId: credentials.deviceId,
        homeserverUrl: credentials.baseUrl,
        oidcData: undefined,
        slidingSyncVersion: SlidingSyncVersion.Native,
      });

      // Verify the session is valid by making a server request
      try {
        this.profile = await this.instance.getProfile(credentials.userId);
      } catch (error) {
        console.warn("Session validation failed:", error);
        throw new Error("Session is invalid or expired");
      }

      this.syncService = await this.instance.syncService().finish();

      if (!this.syncService) {
        throw new Error("Failed to initialize sync service");
      }

      await this.syncService.start();

      // Update atoms so providers can react to the initialized service
      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);

      return true;
    } catch (error) {
      console.warn("Failed to restore session:", error);

      // Clear both credentials and crypto store to ensure clean state
      MatrixStorage.clearLoginCredentials();
      await this.clearCryptoStore();

      // Reset the instance so it can be recreated fresh
      this.instance = null;
      this.syncService = null;

      // Clear atoms
      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
      MatrixJotaiStore.set(MatrixAtoms.syncService, null);

      return false;
    }
  };

  /** Call this after logging in to create a new client instance with the provided account.  */
  public static setup = async (params: Session) => {
    // Clear any existing crypto store to prevent device ID mismatches
    await this.clearCryptoStore();

    // Stop and clear existing instances
    if (this.syncService) await this.syncService.stop();
    this.instance = null;
    this.syncService = null;

    // Save credentials for future auto-login
    MatrixStorage.saveLoginCredentials({
      accessToken: params.accessToken,
      refreshToken: params.refreshToken,
      userId: params.userId,
      deviceId: params.deviceId,
      baseUrl: params.homeserverUrl,
    });

    // Create a fresh client instance and configure it with the session + sliding sync
    await this.initialize(params.homeserverUrl);

    if (!this.instance) throw new Error("Failed to initialize client");

    // Use local variable to help TypeScript with type narrowing
    const client: ClientInterface = this.instance;

    await client.restoreSession({
      accessToken: params.accessToken,
      refreshToken: params.refreshToken,
      userId: params.userId,
      deviceId: params.deviceId,
      homeserverUrl: params.homeserverUrl,
      oidcData: undefined,
      slidingSyncVersion: SlidingSyncVersion.Native,
    });

    // Verify the session is valid by making a server request
    // Use the params.userId since client.userId() might not be populated yet
    try {
      this.profile = await client.getProfile(params.userId);
    } catch (error) {
      console.warn("Session validation failed:", error);
      throw new Error("Session is invalid or expired");
    }

    this.syncService = await client.syncService().finish();

    if (!this.syncService) throw new Error("Failed to initialize sync service");

    await this.syncService.start();
    await client.encryption().waitForE2eeInitializationTasks();

    // Check if we need to bootstrap cross-signing or enable backups
    try {
      const encryption = client.encryption();
      const backupExists = await encryption.backupExistsOnServer();
      console.log("Backup exists on server:", backupExists);
      console.log(
        "Current verification state:",
        encryption.verificationState(),
      );

      // If no backup exists and we're the only device, we might need to set one up
      const isLastDevice = await encryption.isLastDevice();
      console.log("Is last device:", isLastDevice);

      if (!backupExists) {
        console.log("Enabling backups for cross-signing...");
        await encryption.enableBackups();
      }

      // Update atoms so providers can react to the initialized service
      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
    } catch (error) {
      console.warn("Failed to check backup/verification status:", error);
    }
  };

