  /** Deactivate the user's account permanently
   * Warning: This is irreversible and will delete all user data */
  public static deactivateAccount = async (password: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    try {
      // First request with undefined auth_data (will always fail per UIA spec)
      try {
        await this.instance.deactivateAccount(undefined, true);
      } catch {
        // Expected to fail
      }

      console.log(this.instance.userId(), "userId");
      const userId = this.instance.userId();
      if (!userId) throw new Error("User ID not found");

      const authData = new AuthData.Password({
        passwordDetails: AuthDataPasswordDetails.create({
          identifier: userId,
          password,
        }),
      });

      // Step 4: Second request with auth data
      await this.instance.deactivateAccount(authData, true);

      // After successful deactivation, clean up local data
      await this.logout();
    } catch (error) {
      console.error("Failed to deactivate account:", error);
      throw error;
    }
  };

