  /** Create a room with optional image avatar */
  /** Get or create a direct room with a user */
  public static getOrCreateDirectRoom = async (
    userId: string,
  ): Promise<string> => {
    if (!this.instance) throw new Error("Client not initialized");

    try {
      // Check if a direct room already exists with this user
      const rooms = this.instance.rooms();
      for (const room of rooms) {
        const roomInfo = await room.roomInfo();
        if (roomInfo?.isDirect) {
          const members = await room.members();
          const memberList = members.nextChunk(100000) ?? [];
          const hasUser = memberList.some((member) => member.userId === userId);
          if (hasUser) {
            return room.id();
          }
        }
      }

      // If no direct room exists, create one
      const roomOptions: CreateRoomParameters = {
        name: undefined,
        topic: undefined,
        preset: RoomPreset.PrivateChat,
        avatar: undefined,
        isEncrypted: true,
        isDirect: true,
        visibility: new RoomVisibility.Private(),
        invite: [userId],
        powerLevelContentOverride: undefined,
        joinRuleOverride: undefined,
        historyVisibilityOverride: undefined,
        canonicalAlias: undefined,
      };

      const roomId = await this.instance.createRoom(roomOptions);
      return roomId;
    } catch (error) {
      throw new Error(`Failed to get or create direct room: ${error}`);
    }
  };

  public static createRoom = async (
    roomName: string,
    type: "private" | "public",
    image: Asset | null,
    roomTopic?: string,
  ): Promise<string> => {
    try {
      const roomOptions: CreateRoomParameters = {
        name: roomName,
        topic: roomTopic,
        preset:
          type === "private" ? RoomPreset.PrivateChat : RoomPreset.PublicChat,
        avatar: undefined,
        isEncrypted: type === "private",
        isDirect: false,
        visibility:
          type === "private"
            ? new RoomVisibility.Private()
            : new RoomVisibility.Public(),
        invite: [],
        powerLevelContentOverride: undefined,
        joinRuleOverride: undefined,
        historyVisibilityOverride: undefined,
        canonicalAlias: undefined,
      };

      if (!this.instance) throw new Error("Client not initialized");

      const roomId = await this.instance.createRoom(roomOptions);

      if (image?.base64) {
        const room = this.instance.getRoom(roomId);

        const bytes = Buffer.from(image.base64, "base64");
        const type = image.type ?? "image/jpeg";

        if (!room) throw new Error("Room not found");
        await room.uploadAvatar(type, bytes.buffer, {
          height: BigInt(32),
          width: BigInt(32),
          mimetype: type,
          size: BigInt(image.fileSize ?? 0),
          thumbnailInfo: {
            height: BigInt(32),
            width: BigInt(32),
            mimetype: type,
            size: BigInt(image.fileSize ?? 0),
          },
          thumbnailSource: undefined,
          blurhash: "",
          isAnimated: false,
        });
      }

      return roomId;
    } catch (error) {
      throw new Error(`Failed to create room: ${error}`);
    }
  };

