  public static getReadReceipts = async (event: EventTimelineItem) => {
    const userIds = Array.from(event.readReceipts.keys()).map(
      (userIds) => userIds,
    );

    // Don't show read receipts for the sender's own message
    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);

    if (!filteredUserIds.length) {
      return [];
    }

    try {
      const profilePromises = filteredUserIds.map((userId) =>
        this.instance?.getProfile(userId),
      );
      const profiles = await Promise.allSettled(profilePromises);
      return profiles
        .filter((p) => p.status === "fulfilled")
        .map((p) => p.value)
        .filter((p) => p !== undefined);
    } catch (error) {
      console.error("Failed to get read receipt users:", error);
      return [];
    }
  };

