   213→        "global",
   214→        "underride",
   215→        ".m.rule.room_one_to_one",
   216→        actions,
   217→      );
   218→    }
   219→  },
   220→
   221→  /**
   222→   * Configure notifications for mentions (@username or @room)
   223→   * Uses both newer override rules and older content rules for compatibility
   224→   */
   225→  setMentionsEnabled: async (enabled: boolean): Promise<boolean> => {
   226→    // Newer Matrix spec uses override rules
   227→    const overrideRules = [
   228→      ".m.rule.is_user_mention", // New: Matches @username mentions
   229→      ".m.rule.contains_display_name", // Matches display name
   230→      ".m.rule.is_room_mention", // New: Matches @room mentions
   231→      ".m.rule.roomnotif", // Old: Matches @room
   232→    ];
   233→
   234→    // Older Matrix spec uses content rules
   235→    const contentRules = [
   236→      ".m.rule.contains_user_name", // Old: Matches @username
   237→    ];
   238→
   239→    const overrideResults = await Promise.all(
   240→      overrideRules.map((ruleId) =>
   241→        PushRulesService.setRuleEnabled("global", "override", ruleId, enabled),
   242→      ),
   243→    );
   244→
   245→    const contentResults = await Promise.all(
   246→      contentRules.map((ruleId) =>
   247→        PushRulesService.setRuleEnabled("global", "content", ruleId, enabled),
   248→      ),
   249→    );
   250→
   251→    return [...overrideResults, ...contentResults].every((r) => r);
   252→  },
   253→
   254→  /**
   255→   * Configure notifications for room invitations
   256→   * Uses the .m.rule.invite_for_me override rule
   257→   */
   258→  setInvitationsEnabled: async (enabled: boolean): Promise<boolean> => {
   259→    return await PushRulesService.setRuleEnabled(
   260→      "global",
   261→      "override",
   262→      ".m.rule.invite_for_me",
   263→      enabled,
   264→    );
   265→  },
   266→
   267→  /** Get current notification settings from push rules */
   268→  getNotificationSettings: async (): Promise<{
   269→    groupChats: NotificationLevel;
   270→    directChats: NotificationLevel;
   271→    mentions: boolean;
   272→    invitations: boolean;
   273→  } | null> => {
   274→    const rules = await PushRulesService.getPushRules();
   275→
   276→    if (!rules || !rules.global) return null;
   277→
   278→    // Determine group chat level
   279→    const messageRule = rules.global.underride?.find(
   280→      (r) => r.rule_id === ".m.rule.message",
   281→    );
   282→    const groupChats: NotificationLevel = messageRule?.enabled
   283→      ? "all"
   284→      : "mentions";
   285→
   286→    // Determine direct chat level
   287→    const dmRule = rules.global.underride?.find(
   288→      (r) => r.rule_id === ".m.rule.room_one_to_one",
   289→    );
   290→    const directChats: NotificationLevel = dmRule?.enabled ? "all" : "none";
   291→
   292→    // Determine mentions - check both new and old rules
   293→    const newMentionRule = rules.global.override?.find(
   294→      (r) => r.rule_id === ".m.rule.is_user_mention",
   295→    );
   296→    const oldMentionRule = rules.global.content?.find(
   297→      (r) => r.rule_id === ".m.rule.contains_user_name",
   298→    );
   299→    const displayNameRule = rules.global.override?.find(
   300→      (r) => r.rule_id === ".m.rule.contains_display_name",
   301→    );
   302→
   303→    // Mentions are enabled if any of the mention rules are enabled
   304→    const mentions =
   305→      (newMentionRule?.enabled ?? false) ||
   306→      (oldMentionRule?.enabled ?? false) ||
   307→      (displayNameRule?.enabled ?? true);
   308→
   309→    // Determine invitations - check override section (not underride)
   310→    const inviteRule = rules.global.override?.find(
   311→      (r) => r.rule_id === ".m.rule.invite_for_me",
   312→    );
   313→    const invitations = inviteRule?.enabled ?? true;
   314→
   315→    return {
   316→      groupChats,
   317→      directChats,
   318→      mentions,
   319→      invitations,
   320→    };
   321→  },
   322→};
   323→
   324→/** Helper function to get actions array for a notification level */
   325→function getActionsForLevel(
   326→  level: NotificationLevel,
   327→): (PushRuleAction | string)[] {
   328→  switch (level) {
   329→    case "all":
   330→      return [
   331→        "notify",
   332→        { set_tweak: "sound", value: "default" },
   333→        { set_tweak: "highlight", value: false },
   334→      ];
   335→    case "mentions":
   336→      return [
   337→        "notify",
   338→        { set_tweak: "sound", value: "default" },
   339→        { set_tweak: "highlight", value: true },
   340→      ];
   341→    case "none":
   342→      return ["dont_notify"];
   343→  }
   344→}
