  | "dont_notify"
  | "coalesce"
  | { set_tweak: string; value: string | boolean };

export type PushRuleCondition = {
  kind: string;
  key?: string;
  pattern?: string;
  is?: string;
};

export type PushRule = {
  rule_id: string;
  default: boolean;
  enabled: boolean;
  conditions?: PushRuleCondition[];
  actions: (PushRuleAction | string)[];
  pattern?: string;
};

export type PushRuleset = {
  global: {
    override?: PushRule[];
    content?: PushRule[];
    room?: PushRule[];
    sender?: PushRule[];
    underride?: PushRule[];
  };
};

export type NotificationLevel = "all" | "mentions" | "none";

/**
 * Service for managing Matrix Push Rules
 * Push rules determine when notifications should be sent to the user
 */
export const PushRulesService = {
  /** Get all push rules for the current user */
  getPushRules: async (): Promise<PushRuleset | null> => {
    if (!MatrixService.instance) throw new Error("Client not initialized");

    const session = MatrixService.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_GET}`,
        {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
        },
      );

      if (!response.ok) {
        console.error("Failed to get push rules:", response.status);
        return null;
      }

      return await response.json();
    } catch (error) {
      console.error("Failed to fetch push rules:", error);
      return null;
    }
  },

  /** Enable or disable a specific push rule */
  setRuleEnabled: async (
    scope: string,
    kind: string,
    ruleId: string,
    enabled: boolean,
  ): Promise<boolean> => {
    if (!MatrixService.instance) throw new Error("Client not initialized");

    const session = MatrixService.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_ENABLE}${scope}/${kind}/${ruleId}/enabled`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify({ enabled }),
        },
      );

      return response.ok;
    } catch (error) {
      console.error("Failed to set rule enabled state:", error);
      return false;
    }
  },

  /** Set actions for a specific push rule */
  setRuleActions: async (
    scope: string,
    kind: string,
    ruleId: string,
    actions: (PushRuleAction | string)[],
  ): Promise<boolean> => {
    if (!MatrixService.instance) throw new Error("Client not initialized");

    const session = MatrixService.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_SET}${scope}/${kind}/${ruleId}/actions`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify({ actions }),
        },
      );

      return response.ok;
    } catch (error) {
      console.error("Failed to set rule actions:", error);
      return false;
    }
  },

  /**
   * Configure notifications for group chats (rooms with >2 members)
   * Uses the .m.rule.room_one_to_one underride rule
   */
  setGroupChatNotifications: async (
    level: NotificationLevel,
  ): Promise<boolean> => {
    // For group chats, we modify the underride rule that matches rooms with more than 2 members
    // The default rule is ".m.rule.message" which notifies for all messages
    // We need to disable it for "mentions" or "none"

    if (level === "none") {
      // Disable notifications for group chats
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.message",
        false,
      );
    } else if (level === "mentions") {
      // For mentions only, disable the general message rule
      // but keep the mention rules enabled (they're in override/content)
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.message",
        false,
      );
    } else {
      // For "all", enable the message rule
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.message",
        true,
      );
    }
  },

  /**
   * Configure notifications for direct chats (1:1 rooms)
   * Uses the .m.rule.room_one_to_one underride rule
   */
  setDirectChatNotifications: async (
    level: NotificationLevel,
  ): Promise<boolean> => {
    const actions = getActionsForLevel(level);

    if (level === "none") {
      return await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        false,
      );
    } else if (level === "mentions") {
      // For direct chats, "mentions" doesn't make much sense, but we'll keep the rule enabled
      // with notify actions (all messages in DMs are somewhat like mentions)
      return await PushRulesService.setRuleActions(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        actions,
      );
    } else {
      // Enable and set actions for all messages
      const enabled = await PushRulesService.setRuleEnabled(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        true,
      );
      if (!enabled) return false;

      return await PushRulesService.setRuleActions(
        "global",
        "underride",
        ".m.rule.room_one_to_one",
        actions,
      );
    }
  },

  /**
   * Configure notifications for mentions (@username or @room)
   * Uses both newer override rules and older content rules for compatibility
   */
  setMentionsEnabled: async (enabled: boolean): Promise<boolean> => {
    // Newer Matrix spec uses override rules
    const overrideRules = [
      ".m.rule.is_user_mention", // New: Matches @username mentions
      ".m.rule.contains_display_name", // Matches display name
      ".m.rule.is_room_mention", // New: Matches @room mentions
      ".m.rule.roomnotif", // Old: Matches @room
    ];

    // Older Matrix spec uses content rules
    const contentRules = [
      ".m.rule.contains_user_name", // Old: Matches @username
    ];

    const overrideResults = await Promise.all(
      overrideRules.map((ruleId) =>
        PushRulesService.setRuleEnabled("global", "override", ruleId, enabled),
      ),
    );

    const contentResults = await Promise.all(
      contentRules.map((ruleId) =>
        PushRulesService.setRuleEnabled("global", "content", ruleId, enabled),
      ),
    );

    return [...overrideResults, ...contentResults].every((r) => r);
  },

  /**
   * Configure notifications for room invitations
   * Uses the .m.rule.invite_for_me override rule
   */
  setInvitationsEnabled: async (enabled: boolean): Promise<boolean> => {
    return await PushRulesService.setRuleEnabled(
      "global",
      "override",
      ".m.rule.invite_for_me",
      enabled,
    );
  },

  /** Get current notification settings from push rules */
  getNotificationSettings: async (): Promise<{
    groupChats: NotificationLevel;
    directChats: NotificationLevel;
    mentions: boolean;
    invitations: boolean;
  } | null> => {
    const rules = await PushRulesService.getPushRules();

    if (!rules || !rules.global) return null;

    // Determine group chat level
    const messageRule = rules.global.underride?.find(
      (r) => r.rule_id === ".m.rule.message",
    );
    const groupChats: NotificationLevel = messageRule?.enabled
      ? "all"
      : "mentions";

    // Determine direct chat level
    const dmRule = rules.global.underride?.find(
      (r) => r.rule_id === ".m.rule.room_one_to_one",
    );
    const directChats: NotificationLevel = dmRule?.enabled ? "all" : "none";

    // Determine mentions - check both new and old rules
    const newMentionRule = rules.global.override?.find(
      (r) => r.rule_id === ".m.rule.is_user_mention",
    );
    const oldMentionRule = rules.global.content?.find(
      (r) => r.rule_id === ".m.rule.contains_user_name",
    );
    const displayNameRule = rules.global.override?.find(
      (r) => r.rule_id === ".m.rule.contains_display_name",
    );

    // Mentions are enabled if any of the mention rules are enabled
    const mentions =
      (newMentionRule?.enabled ?? false) ||
      (oldMentionRule?.enabled ?? false) ||
      (displayNameRule?.enabled ?? true);

    // Determine invitations - check override section (not underride)
    const inviteRule = rules.global.override?.find(
      (r) => r.rule_id === ".m.rule.invite_for_me",
    );
    const invitations = inviteRule?.enabled ?? true;

    return {
      groupChats,
      directChats,
      mentions,
      invitations,
    };
  },
};

/** Helper function to get actions array for a notification level */
function getActionsForLevel(
  level: NotificationLevel,
): (PushRuleAction | string)[] {
  switch (level) {
    case "all":
      return [
        "notify",
        { set_tweak: "sound", value: "default" },
        { set_tweak: "highlight", value: false },
      ];
    case "mentions":
      return [
        "notify",
        { set_tweak: "sound", value: "default" },
        { set_tweak: "highlight", value: true },
      ];
    case "none":
      return ["dont_notify"];
  }
}

