export const formatLocalPushNotificationMessage = (
  data: NotificationData | undefined,
) => {
  if (!data) return;

  if (data.type === "m.room.member") {
    if (data?.membership === "invite") {
      return {
        title: data.sender_display_name || data.sender || "Unknown Sender",
        message: `${data.sender_display_name || data.sender} invited you to a room`,
        room_id: "",
      };
    }
    if (data?.membership === "join") {
      return {
        title: data.sender_display_name || data.sender || "Unknown Sender",
        message: `${data.sender_display_name || data.sender} joined the room`,
        room_id: "",
      };
    }
    if (data?.membership === "left") {
      return {
        title: data.sender_display_name || data.sender || "Unknown Sender",
        message: `${data.sender_display_name || data.sender} left the room`,
        room_id: "",
      };
    }
  }

  if (data.type === "m.room.encrypted") {
    return {
      title:
        data.room_name ||
        data.sender_display_name ||
        data.sender ||
        "Unknown Sender",
      message: `${data.sender_display_name || data.sender} sent you a new encrypted message`,
      room_id: data.room_id,
    };
  }

  if (data.type === "m.room.message") {
    return {
      title: data.room_name || data.room_id || "Unknown Room",
      message: `${data.sender_display_name || data.sender}: ${data.content_body || ""}`,
      room_id: data.room_id,
    };
  }

  return undefined;
};

