import { atom } from "jotai";
import { atomWithStorage } from "jotai/utils";
import { SecureStoreKeys } from "modules/matrix-client/models";
import {
  JotaiStorageBooleanAdapter,
  JotaiStorageStringAdapter,
} from "modules/storage/utils";

const isPermitted = atom<boolean | null>(null);

const token = atomWithStorage<string>(
  SecureStoreKeys.FCM_TOKEN,
  "",
  JotaiStorageStringAdapter,
);

const hasAllowedNotificationsIntro = atomWithStorage<boolean>(
  SecureStoreKeys.HAS_ALLOWED_NOTIFICATIONS_INTRO,
  false,
  JotaiStorageBooleanAdapter,
);

const hasSeenNotificationsIntro = atomWithStorage<boolean>(
  SecureStoreKeys.HAS_SEEN_NOTIFICATIONS_INTRO,
  false,
  JotaiStorageBooleanAdapter,
);

export const PushNotificationsAtoms = {
  isPermitted,
  hasAllowedNotificationsIntro,
  hasSeenNotificationsIntro,
  token,
};
